        {
          "id": "day_1_date",
          "component": "Text",
          "text": "**Date:** 2025-06-10 (Tuesday)"
        },
        {
          "id": "day_1_neighborhood",
          "component": "Text",
          "text": "**Neighborhood:** Shinjuku"
        },
        {
          "id": "day_1_theme",
          "component": "Text",
          "text": "**Theme:** Cityscapes, Relaxed Exploration, Modern Tokyo"
        },
        {
          "id": "day_1_activities_title",
          "component": "Text",
          "variant": "h5",
          "text": "Activities"
        },
        {
          "id": "day_1_activities_list",
