          "component": "Text",
          "text": "**Neighborhood:** Mitaka, Shibuya"
        },
        {
          "id": "day_2_theme",
          "component": "Text",
          "text": "**Theme:** Anime Immersion, Pop Culture Icon"
        },
        {
          "id": "day_2_activities_title",
          "component": "Text",
          "variant": "h5",
          "text": "Activities"
        },
        {
          "id": "day_2_activities_list",
